<div class="page-heading"><h1>Pelatihan Saya</h1><p>Seluruh kelas yang sudah disetujui dan riwayat pembelajaran Anda.</p></div>
<?php if(!$enrollments) emptyState('Belum ada kelas yang dapat diakses','Pendaftaran yang telah disetujui admin akan muncul di sini.','portal.php?view=registrations','Lihat pendaftaran'); ?>
<div class="portal-grid"><?php foreach($enrollments as $en): $pr=progress($uid,(int)$en['batch_id']);$instructors=rows('SELECT i.name FROM instructors i JOIN program_instructors pi ON pi.instructor_id=i.id JOIN training_batches b ON b.program_slug=pi.program_slug WHERE b.id=? AND i.is_published=1',[$en['batch_id']]); ?><article class="panel"><div class="row"><span class="badge <?= e($en['status']) ?>"><?= $en['status']==='completed'?'Selesai':($en['start_date']>date('Y-m-d')?'Akan datang':($en['end_date']<date('Y-m-d')?'Menunggu penyelesaian':'Aktif')) ?></span><span class="muted"><?= e($en['delivery_format']) ?></span></div><h2 style="margin-top:20px"><?= e($en['title']) ?></h2><p class="muted"><?= e($en['start_date'].' — '.$en['end_date']) ?></p><p class="muted">Instruktur: <?= e(implode(', ',array_column($instructors,'name'))?:'Belum diumumkan') ?></p><div class="progress-track"><span style="width:<?= $pr['percent'] ?>%"></span></div><p class="muted"><?= $pr['percent'] ?>% aktivitas selesai</p><div class="actions"><a class="btn" href="portal.php?view=learning&amp;batch=<?= (int)$en['batch_id'] ?>">Buka ruang belajar</a></div></article><?php endforeach; ?></div>
